 String kind(String t,boolean stay){String l=t.toLowerCase();if(stay){if(l.contains("riad"))return "Riad";if(l.contains("hostel"))return "Hostel";if(l.contains("apartment"))return "Apartment";if(l.contains("camp")||l.contains("kasbah")||l.contains("guesthouse")||l.contains("auberge")||l.contains("dar "))return "Camp / guesthouse";if(l.contains("hotel")||l.contains("resort"))return "Hotel";return "Other";}
  if(l.contains("vegetarian")||l.contains("vegan"))return "Vegetarian";if(l.contains("stall")||l.contains("street")||l.contains("sandwich"))return "Street food";if(l.contains("cafe")||l.contains("caf\u00e9")||l.contains("coffee")||l.contains("tea ")||l.contains("juice"))return "Cafes";if(l.contains("restaurant")||l.contains("grill")||l.contains("seafood")||l.contains("fish")||l.contains("eat at")||l.contains("chez "))return "Restaurants";return "Dishes";}
