 JSONArray tripArr(){try{return new JSONArray(sp.getString("trip","[]"));}catch(Exception e){return new JSONArray();}}
 boolean inTrip(String cid,String n){JSONArray a=tripArr();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optString("c").equals(cid)&&o.optString("n").equals(n))return true;}return false;}
 void addTrip(String cid,String cn,String n,int min){if(inTrip(cid,n))return;JSONArray a=tripArr();try{JSONObject o=new JSONObject();o.put("c",cid);o.put("cn",cn);o.put("n",n);o.put("m",min);a.put(o);}catch(Exception e){}sp.edit().putString("trip",a.toString()).apply();Toast.makeText(this,"Added to your trip",Toast.LENGTH_SHORT).show();}
 void delTrip(int idx){JSONArray a=tripArr();JSONArray b=new JSONArray();for(int i=0;i<a.length();i++)if(i!=idx)b.put(a.opt(i));sp.edit().putString("trip",b.toString()).apply();}
