 class MapV extends View{String sel;Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float[][] xy;MapV(String s){super(Main.this);sel=s;}
  double minLat=99,maxLat=-99,minLon=99,maxLon=-99;
  float px(double lon){return (float)((lon-minLon)/(maxLon-minLon)*(getWidth()-dp(60))+dp(30));}float py(double lat){return (float)((maxLat-lat)/(maxLat-minLat)*(getHeight()-dp(60))+dp(30));}
  protected void onDraw(Canvas c){try{if(minLat>90){for(int i=0;i<cities.length();i++){JSONObject o=cities.getJSONObject(i);minLat=Math.min(minLat,o.getDouble("lat"));maxLat=Math.max(maxLat,o.getDouble("lat"));minLon=Math.min(minLon,o.getDouble("lon"));maxLon=Math.max(maxLon,o.getDouble("lon"));}minLat-=.8;maxLat+=.8;minLon-=1;maxLon+=1;}
   p.setColor(0xFFDCEBF0);c.drawRect(0,0,getWidth(),getHeight(),p);p.setColor(0x66FFFFFF);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));for(int i=0;i<getWidth();i+=dp(48))c.drawLine(i,0,i,getHeight(),p);for(int i=0;i<getHeight();i+=dp(48))c.drawLine(0,i,getWidth(),i,p);
   p.setStyle(Paint.Style.FILL);xy=new float[cities.length()][2];for(int i=0;i<cities.length();i++){JSONObject o=cities.getJSONObject(i);float x=px(o.getDouble("lon")),y=py(o.getDouble("lat"));xy[i][0]=x;xy[i][1]=y;boolean on=o.getString("id").equals(sel);p.setColor(on?TERRA:GREEN);c.drawCircle(x,y,dp(on?9:6),p);p.setColor(Color.WHITE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));c.drawCircle(x,y,dp(on?9:6),p);p.setStyle(Paint.Style.FILL);p.setColor(INK);p.setTextSize(dp(on?12:10));p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));c.drawText(o.getString("name"),x+dp(8),y+dp(4),p);}}catch(Exception e){}}
  int hit(float x,float y){int b=-1;float bd=dp(36)*dp(36);if(xy==null)return -1;for(int i=0;i<xy.length;i++){float d=(xy[i][0]-x)*(xy[i][0]-x)+(xy[i][1]-y)*(xy[i][1]-y);if(d<bd){bd=d;b=i;}}return b;}}
