  TextView t=head("Morocco map",20,INK);t.setBackground(rect(0xE6FFFFFF,18));t.setPadding(dp(18),dp(12),dp(18),dp(12));FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(-2,-2);tp.setMargins(dp(64),dp(46),0,0);f.addView(t,tp);
