 void share(String text){try{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,tr("Share")));}catch(Exception e){}}
 void shareTrip(){JSONArray a=tripArr();if(a.length()==0){Toast.makeText(this,tr("Your trip is empty. Add places first."),Toast.LENGTH_LONG).show();return;}
  StringBuilder sb=new StringBuilder(tr("My Morocco trip")+" (Zaeir)\n");int day=1,used=0;boolean first=true;
  for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;int m=o.optInt("m",60);if(first||(used+m>360&&used>0)){sb.append("\n").append(tf("Day %d",day)).append(":\n");day++;used=0;first=false;}used+=m;sb.append("- ").append(o.optString("n")).append(" (").append(o.optString("cn")).append(")\n");}
  share(sb.toString());}

